 function sphere(parent,r,material,x,y,z,sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,24,16),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;parent.add(m);return m;}
 function segment(a,b,r,m){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(r,r*.94,d.length(),24),m);mesh.position.copy(A).add(B).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());body.add(mesh);mesh.castShadow=true;return mesh;}
 head.scale.set(.88,1.12,.91);hair.scale.set(.90,1.08,.94);nose.position.z=.137;nose.scale.set(.66,.83,1.1);sphere(body,.077,skin,0,1.525,.018,.95,.70,1.08);
