 function fit(mesh,a,b){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A);mesh.position.copy(A).add(B).multiplyScalar(.5);mesh.scale.y=d.length()/mesh.geometry.parameters.height;mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());}
